export interface DynamicComponentProps {
  // Syncs up with ModuleFederation 'name'
  remote: string;

  // Syncs up with ModuleFederation 'exposes'
  module: string;

  // This will normally be remoteEntry.js
  url: string;

  // The componentProps will be passed into the mfe init function as part
  // of the config object.
  //
  // This information must be able to be serialized
  // and deserialized with JSON.parse(JSON.stringify(yourValue)).
  // Do not include functions or circular pointers.
  //
  // If this data changes, the changes
  // will not be propagated into the MFE.
  // If you want to pass data that will change into an mfe please use the mfe
  // event functions addMfeEventListener() and dispatchMfeEvent()
  componentProps?: Record<string, any>;

  // The name of the class to put on the dynamic component
  className?: string;

  //When you bootstrap using another instance of React,
  //There is a disconnect between routers. The child mfe needs to
  //use a MemoryRouter to get around this and listen for 'route-change'
  //events fired by the ApplicationShell.  This variable can let
  //the mfe know how much of the url to truncate before calling navigate().
  //Example: 'mfe-1/*' is where this mfe is injected, so when listening
  //for a route change to mfe-1/page-1, the callback can modify the string to
  //be navigate([page-1]);
  injectionRoute?: string;

  //NOTE: Neon components and mfe-utils translate function use a different mechanism than this for doing their jobs.
  locale?: string

  // By default the dynamic component will output errors into the console without throwing anything
  // This prevents code execution from being unexpectedly stopped.
  // If a developer wants to catch and handle thrown exceptions set this to true
  throwErrors?: boolean
}